// Modified method to find the least common supertype of two classes
public JSType getLeastSupertype(JSType that) {
    // Check if that is not a RecordType
    if (!that.isRecordType()) {
        return super.getLeastSupertype(that);
    }
    // Create a RecordTypeBuilder
    RecordTypeBuilder builder = new RecordTypeBuilder(registry);
    // Iterate over properties to compare and add to the builder
    for (String property : properties.keySet()) {
        if (that.toMaybeRecordType().hasProperty(property) &&
            that.toMaybeRecordType().getPropertyType(property).isEquivalentTo(getPropertyType(property))) {
            builder.addProperty(property, getPropertyType(property), getPropertyNode(property));
        }
    }
    // Return the built RecordType
    return builder.build();
}

